css:
@page {
    margin: 0;
    size: A4;
}
body.print-format {
    color: #000;
}

:root {
    --brand-primary: #502394;
    --brand-secondary: #14B8A6;
    --brand-primary-light: #f3e8ff;
    --brand-light-gray: #FAF9F8;
    --brand-border-color: #dee2e6;
    --text-color-primary: #212529;
    --text-color-secondary: #6c757d;
}

/* ========== CONTENEDOR PRINCIPAL ========== */
.print-format-container {
    margin: 0;
    max-width: 100%;
}


html, body {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format-builder, .print-format {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format-container {
    margin: 0 !important;
    padding: 0 !important;
    max-width: 100% !important;
}
.page {
    width: 100%;
    min-height: 297mm;
    padding: 25px 40px 0px 40px;
    box-sizing: border-box;
    page-break-after: always;
}
.print-side-line {
    position: absolute;
    top: 0;
    left: 0;
    width: 18px;
    height: 100%;
    background-color: var(--brand-primary);
    z-index: 2;
}
.page-fixed {
    height: 297mm;
    overflow: hidden;
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: "Helvetica Neue", Arial, sans-serif !important;
}

body {
  font-family: "Helvetica Neue", Arial, sans-serif;
  color: #2b2f33;
}
.page-table {
    display: table;
    width: 100%;
    height: 100%;
}

.page-top {
    display: table-row;
}

.page-bottom {
    display: table-row;
    height: 100%;
    vertical-align: bottom;
}

.header {
  display: table;
  width: 100%;
  font-size: 11px;
  letter-spacing: 1.5px;
  color: #6b7280;
  text-transform: uppercase;
  margin-bottom: 36px;
}

.header-left {
  display: table-cell;
  text-align: left;
  vertical-align: top;
}

.header-right {
  display: table-cell;
  text-align: right;
  vertical-align: top;
  font-size: 11px;
  color: #6b7280;
  text-transform: none;
  letter-spacing: 0;
}

.divider-blue {
  width: 52px;
  height: 4px;
    background: var(--brand-primary);
  margin-bottom: 16px;
}

.section-label {
    color: var(--brand-primary);
  font-size: 11px;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.main-title {
  font-size: 38px;
  font-weight: bold;
  line-height: 1.2;
  color: #111827;
  margin-bottom: 16px;
}

.divider-orange {
  width: 52px;
  height: 4px;
    background: var(--brand-secondary);
  margin-bottom: 28px;
}

.label {
  font-size: 10px;
  color: #6b7280;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-bottom: 3px;
  margin-top: 18px;
  display: block;
  border: none;
  background: none;
  padding: 0;
  text-align: left;
}

.value {
  font-size: 18px;
  font-weight: bold;
  color: #111827;
  display: block;
  border: none;
  background: none;
  padding: 0;
}

.push-down {
  height: 210mm;
}
.cover-bottom {
    position: absolute;
  bottom: 0;
  left: 40px;
  right: 40px;
}

.stats {
  display: table;
  width: 100%;
  margin-bottom: 16px;
  margin-left: 5px;
}

.stat-item {
  display: table-cell;
  text-align: left;
  vertical-align: top;
  padding-right: 10px;
}

.stat-label {
  font-size: 9px;
  color: #6b7280;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 4px;
  display: block;
}

.stat-value {
  font-size: 20px;
  font-weight: bold;
  display: block;
}

.green  { color: #16a34a; }
.blue   { color: #1d4ed8; }
.orange { color: var(--brand-secondary); }

.note {
  background: #f3f4f6;
  padding: 12px 14px;
  border-radius: 6px;
  font-size: 10px;
  color: #6b7280;
  margin-bottom: 16px;
}
.page-fixed .footer {
  position: absolute;
  bottom: 20px;
  left: 40px;
  right: 40px;

  display: table;
  width: calc(100% - 80px);

  font-size: 10px;
  color: #9ca3af;
  border-top: 0.5px solid #e5e7eb;
  padding-top: 8px;
  display:none;
}

.brand-logo-cover {
    display: block;
    margin-top: 15px; 
    text-align: left;
}

.brand-logo-cover img {
    height: 32px; 
    width: auto;
    display: inline;
}

.page-fixed .footer {
    z-index: 10;
    background-color: white; 
}
.page-flow {
    width: 100%;
    min-height: 297mm;
    max-height: fit-content;
    padding: 25px 40px 0 40px;
    box-sizing: border-box;

    position: relative;
    page-break-after: always;
}
.page-flow .footer {
    position: relative;
    bottom: 20px;
    left: 40px;
    right: 40px;
    margin-top: 30px;

      display: table;
      width: calc(100% - 80px);


      font-size: 10px;
      color: #9ca3af;
      border-top: 0.5px solid #e5e7eb;
      padding-top: 8px;
        display:none;
}
.footer-left   { display: table-cell; text-align: left; }
.footer-center { display: table-cell; text-align: center; }
.footer-right  { display: table-cell; text-align: right; }
/* Estilos para la Página 2 - Resumen Ejecutivo */
.page-number-box {
    background: var(--brand-primary);
    color: white;
    width: 28px;
    height: 28px;
    display: inline-block;
    text-align: center;
    line-height: 28px;
    font-weight: bold;
    margin-right: 10px;
    vertical-align: middle;
}

.section-header {
    margin-bottom: 25px;
}

.section-title-text {
    display: inline-block;
    vertical-align: middle;
}

.section-title-text h2 {
    font-size: 18px;
    text-transform: uppercase;
    color: #111827;
    font-weight: bolder; 
    letter-spacing: 0.5px;
}

.section-title-text p {
    font-size: 11px;
    color: #6b7280;
}

/* Layout de Tabla y Gauge */
.executive-summary-grid {
    display: table;
    width: 100%;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    margin-bottom: 20px;
}

.gauge-container {
    display: table-cell;
    width: 65%;
    vertical-align: middle;
    text-align: center;
    padding: 20px;
}

.table-container {
    display: table-cell;
    width: 65%;
    padding: 15px;
    vertical-align: top;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
}

.data-table th {
    text-align: left;
    color: #6b7280;
    text-transform: uppercase;
    padding-bottom: 8px;
    border-bottom: 1px solid #f3f4f6;
}

.data-table td {
    padding: 6px 0;
    border-bottom: 1px solid #f3f4f6;
}

.score-bold { font-weight: bold; color: #111827; }
.score-yellow { color: #16a34a; font-weight: bold; }

/* Cajas de participación (Lideres, Pares, etc) */
.participation-row {
    display: table;
    width: 100%;
    margin-bottom: 25px;
    border-spacing: 10px 0;
}

.participation-card {
    display: table-cell;
    width: 25%;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    text-align: center;
    padding: 10px;
}

.participation-label { font-size: 8px; color: #6b7280; text-transform: uppercase; }
.participation-value { font-size: 14px; font-weight: bold; display: block; }
.participation-percent { font-size: 9px; color: #16a34a; }

/* Contenedor del Gráfico Radar */
.chart-box {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 20px;
}

.chart-title {
    text-align: left;
    font-size: 12px;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: 10px;
}

/* Deja que el contenedor crezca según el contenido */
.chart-container {
    width: 100%;
    min-height: 500px; /* Le damos un espacio base grande */
    text-align: center;
    overflow: visible; /* Cambiado de hidden para evitar cortes */
    margin: 20px 0;
}


.chart-img {
    width: 100%;       
    max-width: 900px;
    height: auto;     
    max-height: 700px;
    display: block;
    margin: 0 auto;
}
/* COLORES */
.bar-auto { background-color: var(--brand-primary); }
.bar-lider { background-color: #FF7F50; }
.bar-pares { background-color: #10b981; }
.bar-colab { background-color: #ef4444; }
.bar-otros { background-color: var(--brand-secondary); }

/* HEADER */
.section-divider {
    border: 0;
    border-top: 1px solid #e5e7eb;
    margin-top: 10px;
    margin-bottom: 15px;
}

/* LEGEND */
.legend-container {
    margin-bottom: 15px;
    font-size: 9px;
    color: #6b7280;
}

.legend-item {
    display: inline-block;
    margin-right: 12px;
}

.dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    display: inline-block;
    margin-right: 4px;
}

/* HEADER TABLA */
.attribute-table-header-table {
    width: 100%;
    border-bottom: 1px solid #eee;
    margin-bottom: 10px;
}

.attribute-table-header-table td {
    font-size: 9px;
    text-transform: uppercase;
    font-weight: bold;
    color: #6b7280;
}

.col-label { width: 60px; }
.col-bar { width: auto; }
.col-score {
    width: 60px;
    text-align: center;
}

.col-leader {
    width: 70px;
    text-align: center;
    color: #f97316;
}

/* CARD */
.attribute-card {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 10px;
    margin-bottom: 10px;
    page-break-inside: avoid;
}

.theme-header {
    background-color: #f8fafc;
    color: var(--brand-primary);
    font-weight: bold;
    text-transform: uppercase;
    font-size: 13px;
    padding: 6px 10px;
    border-radius: 4px;
    margin-top: 14px;
    margin-bottom: 8px;
}
.attribute-header {
    margin-bottom: 8px;
}

.attribute-title {
    font-size: 14px;
    font-weight: bold;
    color: #111827;
}

.attribute-desc {
    font-size: 10px;
    color: #9ca3af;
    margin-left: 8px;
}

/* FILAS */
.bar-row-table {
    width: 100%;
    border-collapse: collapse;
}

.bar-row-table td {
    vertical-align: middle;
}

/* COLUMNAS */
.bar-label {
    width: 60px;
    font-size: 9px;
    color: #6b7280;
}



.bar-container {
    width: 100%;
    background-color: #f3f4f6;
    height: 8px;
    border-radius: 4px;
}

.bar-fill {
    height: 100%;
    border-radius: 4px;
}

/* VALORES */
.bar-value {
    width: 60px;
    text-align: center;
    font-size: 10px;
    font-weight: bold;
    color: #2f3b6d;
}

.leader-avg-value {
    width: 70px;
    text-align: center;
    font-size: 11px;
    color: #f97316;
}

.analysis-section {
    margin-bottom: 30px;
}

.analysis-header {
    display: flex;
    align-items: center;
    font-size: 12px;
    font-weight: bold;
    margin-bottom: 10px;
    text-transform: uppercase;
}

.dot-indicator {
    width: 10px;
    height: 10px;
    border-radius: 2px;
    margin-right: 8px;
}

.bg-green { background-color: #16a34a; }
.bg-orange { background-color: var(--brand-secondary); }

.table-analysis {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    margin-bottom: 20px;
}

.table-analysis th {
    text-align: left;
    color: #9ca3af;
    font-weight: normal;
    padding: 8px;
    border-bottom: 1px solid #e5e7eb;
}

.table-analysis td {
    padding: 10px 8px;
    border-bottom: 1px solid #f3f4f6;
    vertical-align: middle;
}

.rank-box {
    background: #f3f4f6;
    color: #6b7280;
    width: 20px;
    height: 20px;
    display: block;
    text-align: center;
    line-height: 20px;
    border-radius: 4px;
}

.question-text-cell { width: 55%; }
.question-dim { font-size: 8px; color: #9ca3af; display: block; }
.score-badge {
    padding: 4px 8px;
    border-radius: 4px;
    font-weight: bold;
    display: inline-block;
}

.badge-green { background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }
.badge-red { background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }

.reflection-box {
    background: #f8fafc;
    border-radius: 8px;
    padding: 15px;
    font-size: 10px;
    color: #475569;
    border-left: 4px solid #cbd5e1;
}
/* Escala de colores del Mapa de Calor */
.heat-box {
    width: 38px;
    height: 24px;
    line-height: 24px;
    text-align: center;
    border-radius: 4px;
    font-size: 10px;
    font-weight: bold;
    display: inline-block;
    margin: 2px;
    vertical-align: middle;
}


.v-low  { background-color: #fca5a5; color: #7f1d1d; }   /* rojo medio */
.low    { background-color: #fde68a; color: #78350f; }   /* amarillo medio */
.mid    { background-color: #86efac; color: #14532d; }   /* verde claro */
.high   { background-color: #4ade80; color: #14532d; }   /* verde más fuerte */
/* Tabla de Mapa de Calor */
.heatmap-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
}

.heatmap-table th {
    font-size: 9px;
    color: #6b7280;
    text-transform: uppercase;
    padding: 8px;
    text-align: center;
    border-bottom: 2px solid #e5e7eb;
}

.heatmap-table td {
    padding: 6px 4px;
    border-bottom: 1px solid #f3f4f6;
    font-size: 10px;
}
.theme-row-header {
    background-color: #f1f5f9; 
    color: var(--brand-primary);
    font-weight: bolder;
    text-transform: uppercase;
    font-size: 12px; 
    letter-spacing: 1.2px; 
    padding: 10px 8px !important;
    border-top: 2px solid var(--brand-primary); 

}
.dimension-row-header {
    background-color: #f8fafc;
    color: var(--brand-primary);
    font-weight: bold;
    text-transform: uppercase;
    font-size: 10px;
    padding: 8px !important;
    letter-spacing: 1px;
}

.legend-heatmap {
    display: flex;
    gap: 10px;
    font-size: 8px;
    margin-bottom: 15px;
    align-items: center;
}
/* Barras de Brecha */
.gap-bar-container {
    width: 100%;
    height: 14px;
    background: #f1f5f9;
    position: relative;
    border-radius: 2px;
    margin-top: 4px;
}
.gap-fill-others {
    height: 100%;
    background: #cbd5e1; 
    position: absolute;
}
.gap-fill-red {
    height: 100%;
    background: #fecaca; 
    position: absolute;
    right: 0;
    border-right: 2px solid #ef4444;
}
.gap-marker-auto {
    position: absolute;
    top: -4px;
    height: 22px;
    width: 2px;
    background: var(--brand-primary);
    z-index: 10;
}

/* Etiquetas de dispersión */
.dispersion-box {
    display: table;
    width: 100%;
    margin-top: 20px;
}
.dispersion-col {
    display: table-cell;
    width: 50%;
    padding: 10px;
}
.sigma-value {
    font-weight: bold;
    float: right;
}
.text-red { color: #dc2626; }
.text-green { color: #16a34a; }
/* TABLA PRINCIPAL */
/* TABLA */
.matrix-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 10px;
}

/* CUADRANTE */
.matrix-quadrant {
    width: 50%;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 12px;
    vertical-align: top;
}

/* TITULOS */
.quadrant-title {
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: 6px;
}

.quadrant-subtitle {
    font-size: 8px;
    color: #9ca3af;
    margin-bottom: 10px;
}

/* LISTA SEGURA (SIN UL/LI) */
.item-list {
    display: block;
    width: 100%;
}

/* ITEM */
.item {
    display: block;
    margin-bottom: 8px;
    padding-left: 10px;
    position: relative;
}

/* BULLET */
.item:before {
    content: "•";
    position: absolute;
    left: 0;
    top: 0;
    font-weight: bold;
    color: #9ca3af;
}

/* TEXTO */
.item-title {
    font-size: 9px;
    font-weight: bold;
    display: block;
    word-break: break-word;
}

.item-meta {
    font-size: 9px;
    color: #6b7280;
    display: block;
}

/* COLORES */
.green { color: #16a34a; }
.purple { color: #7B24FF; }
.red { color: #dc2626; }
.teal { color: #14B8A6; }

/* BORDES */
.q-fortaleza-conf { border-top: 4px solid #16a34a; }
.q-fortaleza-desc { border-top: 4px solid var(--brand-primary); }
.q-oportunidad-conf { border-top: 4px solid #dc2626; }
.q-oportunidad-desc { border-top: 4px solid var(--brand-secondary); }

/* MATRIZ SUPERIOR */
.matrix-legend-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 8px;
    text-align: center;
    margin-bottom: 15px;
}

.matrix-legend-table td {
    border: 1px solid #e5e7eb;
    padding: 5px;
}

/* COLORES CELDAS */
.bg-green { background: #f0fdf4; color: #16a34a; }
.bg-purple { background: #eff6ff; color: #7B24FF; }
.bg-red { background: #fef2f2; color: #dc2626; }
.bg-teal { background: #fff7ed; color: #14B8A6; }

/* EMPTY */
.empty-msg {
    font-style: italic;
    color: #9ca3af;
    text-align: center;
    font-size: 9px;
    margin-top: 10px;
}
/* SECCION */
.open-questions-section {
    margin-bottom: 20px;
    page-break-inside: avoid;
}

.question-title-table {
    margin-bottom: 10px;
}

.question-bullet {
    width: 5px;
    height: 5px;
    border-radius: 50%;
}

.question-text {
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
    color: #374151;
    padding-left: 8px;
}

/* CAJA RESPUESTAS */
.answers-box {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 12px;
    background: #ffffff;
}

/* TABLA COLUMNAS */
.answers-table {
    width: 100%;
}

.answers-col {
    width: 50%;
    vertical-align: top;
    padding-right: 10px;
}

/* ITEM */
.answer-item {
    font-size: 9px;
    color: #4b5563;
    margin-bottom: 6px;
    position: relative;
    padding-left: 10px;
}



/* EMPTY */
.empty-msg {
    font-size: 9px;
    color: #9ca3af;
    font-style: italic;
}

.empty-center {
    text-align: center;
    margin-top: 40px;
    color: #9ca3af;
}

/* Colores dinámicos para los bullets */
.bullet-green { background-color: #16a34a; }
.bullet-orange { background-color: var(--brand-secondary); }
.bullet-blue { background-color: var(--brand-primary); }
/* SUBTITULO */
.section-subtitle {
    font-size: 11px;
    color: #6b7280;
    margin: 3px 0 0 0;
    line-height: 1.2;
}

/* HR */
.section-divider-large {
    border: 0;
    border-top: 1px solid #e5e7eb;
    margin: 0 0 40px 0;
    opacity: 0.7;
}

/* CONTENEDOR CENTRADO */
.placeholder-table {
    width: 100%;
    height: 500px; /* controla el centrado vertical */
    border-collapse: collapse;
}

.placeholder-cell {
    text-align: center;
    vertical-align: middle;
    padding: 0 60px;
}

/* ICONO */
.info-icon {
    font-size: 40px;
    width: 50px;
    height:50px;
    color: #7B24FF;
    margin-bottom: 20px;
    text-align: center;
    margin: 0 auto 25px auto; 
}

/* TITULO */
.placeholder-title {
    font-family: sans-serif;
    font-size: 18px;
    font-weight: bold;
    color: #111827;
    margin-bottom: 10px;
}

/* TEXTO */
.placeholder-text {
    font-family: sans-serif;
    font-size: 12px;
    color: #6b7280;
    line-height: 1.6;
    max-width: 480px;
    margin: 0 auto;
}
.section-subtitle {
    font-size: 10px;
    color: #6b7280;
}

/* TIMELINE */
.timeline-table {
    width: 100%;
    margin: 30px 0;
    border-collapse: collapse;
    text-align: center;
}

.timeline-line td {
    border-top: 1px solid #e5e7eb;
    height: 10px;
}

.timeline-step {
    width: 25%;
    vertical-align: top;
}

.timeline-circle {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    color: white;
    margin: 0 auto 6px auto;
    font-size: 12px;
    font-weight: bold;
    line-height: 30px;
}

.timeline-title {
    font-size: 9px;
    font-weight: bold;
    color: #374151;
}

.timeline-sub {
    font-size: 8px;
    color: #9ca3af;
}

/* TITULO */
.section-block-title {
    font-size: 11px;
    font-weight: bold;
    margin-bottom: 12px;
    text-transform: uppercase;
}

/* FOCO */
.foco-box {
    border: 1px dashed #14B8A6;
    border-radius: 8px;
    padding: 12px;
    margin-bottom: 12px;
    background: rgba(20,184,166,0.08);
}

.foco-header-table {
    width: 100%;
}

.foco-title {
    font-size: 11px;
    font-weight: bold;
}

.foco-index {
    background: #14B8A6;
    color: white;
    border-radius: 50%;
    padding: 2px 6px;
    margin-right: 6px;
    font-size: 10px;
}

.foco-badge {
    text-align: right;
    font-size: 9px;
    color: #dc2626;
}

/* CONTEXTO */
.foco-context {
    font-size: 10px;
    color: #4b5563;
    margin: 8px 0;
    border-bottom: 1px solid #eee;
    padding-bottom: 5px;
}

/* FORM */
.foco-form-table {
    width: 100%;
}

.form-label {
    font-size: 8px;
    color: #9ca3af;
    font-weight: bold;
}

.form-line {
    height: 30px;
    border-bottom: 1px dotted #e5e7eb;
}

.mt {
    margin-top: 10px;
}

/* COMPROMISO */
.commitment-title {
    font-size: 11px;
    font-weight: bold;
    margin-bottom: 5px;
}

.commitment-text {
    font-size: 9px;
    color: #6b7280;
}

.signature-table {
    width: 100%;
    margin-top: 30px;
    text-align: center;
}

.signature-table td {
    width: 33%;
    border-top: 1px solid #9ca3af;
    padding-top: 5px;
    font-size: 8px;
    color: #6b7280;
}

.page-break {
    page-break-before: always;
}


.theme-page {
    page-break-inside: avoid;
}


.attribute-card {
    page-break-inside: avoid;
}
